#include "game/game.h"
BwGame g_game;
int main(){ZeroMemory(&g_game,sizeof(g_game));g_game.editor_mode=true;g_game.show_grid=true;g_game.running=true;g_game.render_distance=512;g_game.player_speed=5;g_game.jump_height=1.5f;g_game.gravity=18;g_game.spawn_point=BwVec3(0,BW_EYE_HEIGHT,-8);g_game.quality_scale=1;g_game.fps_average=60;for(int i=0;i<BW_MAX_PLAYERS;++i){g_game.players[i].position=BwVec3((i-1.5f)*1.2f,BW_EYE_HEIGHT,-8);g_game.players[i].grounded=true;g_game.active_slots[i]=i;g_game.pads[i].joined=(i==0);}bw_world_init(&g_game);if(!bw_renderer_open())return 1;DWORD last=GetTickCount();while(g_game.running){DWORD now=GetTickCount(),elapsed=now-last;if(elapsed<16){Sleep(1);continue;}float dt=bw_clamp((float)elapsed/1000,0.001f,.05f);last=now;bw_input_poll(&g_game);for(int i=0;i<BW_MAX_PLAYERS;++i){BwPad *pad=&g_game.pads[i];if(pad->pressed_y&&pad->joined)g_game.running=false;if(i==0&&pad->joined&&pad->pressed_start)g_game.paused=!g_game.paused;if(g_game.paused){if(pad->pressed_b)g_game.paused=false;if(pad->pressed_up)g_game.menu_selection=(g_game.menu_selection+16)%17;if(pad->pressed_down)g_game.menu_selection=(g_game.menu_selection+1)%17;if(g_game.menu_selection==3){if(pad->pressed_left)g_game.render_distance=bw_clamp(g_game.render_distance-64,64,2048);if(pad->pressed_right)g_game.render_distance=bw_clamp(g_game.render_distance+64,64,2048);}else if(g_game.menu_selection==4){if(pad->pressed_left)g_game.player_speed=bw_clamp(g_game.player_speed-.5f,1,20);if(pad->pressed_right)g_game.player_speed=bw_clamp(g_game.player_speed+.5f,1,20);}else if(g_game.menu_selection==5){if(pad->pressed_left)g_game.jump_height=bw_clamp(g_game.jump_height-.25f,.5f,8);if(pad->pressed_right)g_game.jump_height=bw_clamp(g_game.jump_height+.25f,.5f,8);}else if(g_game.menu_selection==6){if(pad->pressed_left)g_game.gravity=bw_clamp(g_game.gravity-1,4,40);if(pad->pressed_right)g_game.gravity=bw_clamp(g_game.gravity+1,4,40);}else if(g_game.menu_selection>=7&&g_game.menu_selection<=9){float *v=g_game.menu_selection==7?&g_game.spawn_point.x:(g_game.menu_selection==8?&g_game.spawn_point.y:&g_game.spawn_point.z);if(pad->pressed_left)*v-=.5f;if(pad->pressed_right)*v+=.5f;*v=bw_clamp(*v,-999,999);}else if(g_game.menu_selection==13){if(pad->pressed_left)g_game.script_npc=(g_game.script_npc+7)%8;if(pad->pressed_right)g_game.script_npc=(g_game.script_npc+1)%8;if(g_game.script_npc>=g_game.npc_count)g_game.script_npc=g_game.npc_count?g_game.npc_count-1:0;}else if(g_game.menu_selection==14){if(pad->pressed_left)g_game.script_condition=(g_game.script_condition+5)%6;if(pad->pressed_right)g_game.script_condition=(g_game.script_condition+1)%6;}else if(g_game.menu_selection==15){if(pad->pressed_left)g_game.script_action=(g_game.script_action+7)%8;if(pad->pressed_right)g_game.script_action=(g_game.script_action+1)%8;}if(pad->pressed_a){if(g_game.menu_selection==0)g_game.paused=false;else if(g_game.menu_selection==1)g_game.editor_mode=!g_game.editor_mode;else if(g_game.menu_selection==2)g_game.automatic_render_distance=!g_game.automatic_render_distance;else if(g_game.menu_selection==10)g_game.spawn_point=g_game.players[i].position;else if(g_game.menu_selection==11)g_game.save_status=bw_world_save(&g_game)?1:-1;else if(g_game.menu_selection==12)g_game.save_status=bw_world_load(&g_game)?2:-2;else if(g_game.menu_selection==16&&g_game.rule_count<BW_MAX_RULES&&g_game.npc_count>0){BwRule *r=&g_game.rules[g_game.rule_count++];r->npc=g_game.script_npc;r->condition=g_game.script_condition;r->action=g_game.script_action;r->parameter=0;r->active=true;}}}else if(pad->pressed_back)g_game.editor_mode=!g_game.editor_mode;}g_game.player_count=0;for(int p=0;p<BW_MAX_PLAYERS;++p)if(g_game.pads[p].connected&&g_game.pads[p].joined)g_game.active_slots[g_game.player_count++]=p;if(g_game.player_count==0){g_game.player_count=1;g_game.active_slots[0]=0;}if(g_game.running&&!g_game.paused){bw_quality_update(&g_game,dt);bw_players_update(&g_game,dt);}if(g_game.automatic_render_distance){float split=g_game.player_count<=1?1:(g_game.player_count==2?.72f:.48f);g_game.render_distance=512*split*g_game.quality_scale;}if(g_game.running)bw_renderer_draw(&g_game);}bw_renderer_close();return 0;}
